  [1218466384198912] = "O serviço de chá em prata dourada é esculpido com lindos emblemas, tornando a hora do chá da tarde ainda mais elegante.",
  [1218466384198656] = "Um estudo de pintura a óleo de um artista famoso; cada pincelada conta uma história.",
  [1218466384198400] = "Um espelho de maquilhagem de parede lindamente esculpido. A superfície do espelho é clara o suficiente para refletir todos os detalhes da sua maquiagem.",
  [1218466384198144] = "Joias de prata pura de alta qualidade. O estilo é simples e antigo, destacando o gosto discreto, porém sofisticado, do usuário.",
  [1218466384197888] = "Prato de porcelana branca com renda fina, quente ao toque. É uma escolha decente para receber convidados de uma família comum.",
  [1218466384197632] = "Fundido em latão, decorado com padrões simples mas elegantes. Adequado para iluminação e decoração diária.",
  [1218466384197376] = "Feito emendando e polindo placas de bordo branco, o estilo é simples e adequado para armazenamento diário em mesa.",
  [1218466384197120] = "Prensado a partir de pó de pedra grosseiramente refinado e meticulosamente esculpido para apresentar uma bela silhueta, tem uma ampla gama de utilizações.",
  [1218466384195840] = "A seda flui com brilho perolado; usando-o, você deve ser a pérola deslumbrante da festa. </>",
  [1218466384195584] = "A caxemira de alta qualidade parece suave como uma nuvem, interpretando o luxo discreto da vida aristocrática. </>",
  [1218466384195328] = "Como um soneto tecido ao luar, cada volta continua a escrever um movimento magnífico e inacabado. </>",
  [1218466384195072] = "O melhor parceiro para os sonhos, fazendo com que o sono tenha uma textura linda. </>",
  [1218466384194816] = "Feito sob medida como uma andorinha, um banquete que ainda não começou está escondido na vibração da bainha traseira. </>",
  [1218466384194560] = "Quando a bainha da roupa roça num poste de luz, há sempre alguns segredos farfalhando nas dobras. </>",
  [1218466384194304] = "Como o abraço de um velho amigo, uma alma delicada envolta numa textura áspera. </>",
  [1218466384194048] = "A costura é densa e a bainha larga, para que você não sinta aperto ao levantar os braços para trabalhar. </>",
  [1218466384192768] = "Os cubos de gelo retêm o frescor e a doçura da carne de marisco, e as fatias são tão cristalinas quanto a neve e o gelo. Obrigado pelo presente das profundezas do mar.",
  [1218466384192512] = "Presunto medalha de ouro produzido por fornecedor real especial; o sabor defumado precipita a delícia do tempo.",
  [1218466384192256] = "Mel suave complementado com carne de porco fumada, excelente companheiro ao pequeno-almoço. Bacon e ovos, meu parceiro.",
  [1218466384192000] = "Anos atrás, um marinheiro chamado Jules inventou uma receita para conservar ostras em salmoura, que ainda hoje é amplamente divulgada.",
  [1218466384191744] = "Mirtilos e morangos dançam uma valsa juntos, revelando um sabor agridoce. Venha, experimente espalhar no pão!",
  [1218259688883712] = "Jornada do Iniciante",
  [1218466384191488] = "Após a fermentação do leite fresco, ele forma uma textura única e deixa um aroma sedutor, bastante apreciado por gatos e ratos.",
  [1218260225754624] = "Comece facilmente a partir daqui; escolhas limitadas podem reduzir o risco.",
  [1218466384191232] = "Utilizando milho duro do Continente Sul, prensado e torrado em lascas douradas e crocantes, perfumadas e deliciosas.",
  [1218466384190976] = "Prensar o açúcar refinado em cubos torna-o um companheiro clássico para o chá preto Loenese.",
  [1218466384186624] = "O licor dourado pálido apresenta bolhas densas e um aroma encantador. Apenas uma taça de cristal de um banquete sofisticado é digna disso.",
  [1218466384186368] = "Vinho tinto clássico de adega, de cor profunda, macio e encorpado, digno de ser envelhecido pelo tempo.",
  [1218466384186112] = "Claro como o orvalho da manhã em uma floresta de bétulas, o licor frio queima com um estímulo semelhante ao de uma chama.",
  [1218466384185856] = "Você quase pode sentir o cedro brotando e rompendo o solo em sua boca, com uma fragrância amadeirada persistente e levemente amarga em seus lábios e língua.",
  [1218466384185600] = "Combinando o leve amargor do cacau com a cremosidade do leite, parece mais uma sobremesa do que uma bebida alcoólica.",
  [1218466384185344] = "O líquido límpido e doce traz uma sensação de embriaguez; cada bolha dança levemente na ponta da língua.",
  [1218466384185088] = "Cerveja dourada com sabor de mel, exalando aroma de malte.",
  [1218466384184832] = "Felicidade que pode ser comprada com algumas moedas; um favorito dos trabalhadores após um longo dia.",
